	@Test
	void nestedExistsOptionalUsesBothMergedSidesAndRejectsFalseOrErrorWitnesses() {
		String condition = """
				EXISTS {
				  ?request :seed ?observed .
				  VALUES (?allowed ?raw) { (:a "1") (:b "bad") }
				  FILTER (?allowed = ?observed && ?observed = ?seed)
				  OPTIONAL {
				    VALUES (?rightKey ?nested) { (:a 1) }
				    FILTER (?rightKey = ?candidate)
				  }
				  FILTER (xsd:integer(?raw) > 0 && BOUND(?nested))
				}
				""";
		assertCase(new Case("nested OPTIONAL/EXISTS merged-pair condition",
				"VALUES ?seed { :a :b :c } ?request :seed ?seed .", RIGHT, condition, COLUMNS,
				List.of("a|a", "b|UNBOUND", "c|UNBOUND")));
	}

	@Test
	void independentProducerKeepsItsBlankNodesAcrossRepeatedOuterKeys() {
		String query = PREFIXES + """
				SELECT ?seed (COUNT(*) AS ?rows) (COUNT(DISTINCT ?stamp) AS ?stamps) WHERE {
				  VALUES ?seed { :a :a :b :c }
				  ?request :seed ?seed .
				  OPTIONAL {
				    { SELECT ?candidate ?stamp WHERE {
				        VALUES ?candidate { :a :b }
				        ?candidate :available true .
				        BIND(BNODE() AS ?stamp)
				    } }
				    FILTER (?candidate = ?seed)
				  }
				} GROUP BY ?seed
				""";
		assertQuery(query, List.of("seed", "rows", "stamps"), List.of("a|2|1", "b|1|1", "c|1|0"));
	}

